import os, sys
try:
    import jinja2
except ImportError:
    sys.path.insert(0, os.path.join(os.getcwd(), 'src')); import jinja2
from jinja2 import Environment
from jinja2.exceptions import TemplateAssertionError, TemplateRuntimeError
env = Environment()
try:
    env.from_string('{{ x|nope }}'); raise AssertionError('expected TemplateAssertionError')
except TemplateAssertionError:
    pass
t = env.from_string('{% if flag %}{{ x|nope }}{% endif %}')
assert t.render(flag=False) == ''
try:
    t.render(flag=True); raise AssertionError('expected TemplateRuntimeError')
except TemplateRuntimeError:
    pass

import os, sys
try:
    import jinja2
except ImportError:
    sys.path.insert(0, os.path.join(os.getcwd(), 'src')); import jinja2
from jinja2.loaders import split_template_path
from jinja2 import TemplateNotFound
assert split_template_path('a/./b.html') == ['a', 'b.html']
assert split_template_path('/a//b') == ['a', 'b']
for bad in ('../x', 'a/../b', 'a/..'):
    try:
        split_template_path(bad); raise AssertionError('expected TemplateNotFound for ' + bad)
    except TemplateNotFound:
        pass

import os, sys
try:
    import jinja2
except ImportError:
    sys.path.insert(0, os.path.join(os.getcwd(), 'src')); import jinja2
from jinja2 import Environment, DictLoader
from jinja2.exceptions import TemplateAssertionError, TemplateRuntimeError, TemplateSyntaxError
env = Environment()
try:
    env.from_string('{% block a %}{% endblock %}{% block a %}{% endblock %}'); raise AssertionError('dup')
except TemplateAssertionError:
    pass
try:
    env.from_string('{% block a required %}x{% endblock %}'); raise AssertionError('required body')
except TemplateSyntaxError:
    pass
e2 = Environment(loader=DictLoader({'p': '{% block b required %}{% endblock %}', 'c': '{% extends "p" %}{% block b %}hi{% endblock %}'}))
assert e2.get_template('c').render() == 'hi'
try:
    e2.get_template('p').render(); raise AssertionError('expected TemplateRuntimeError')
except TemplateRuntimeError:
    pass
